'use strict';
const $=s=>document.querySelector(s);
const state={recipes:[],mood:'All',spirit:'All',savedOnly:false,query:'',active:null,servings:1,unit:'oz'};
let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('evening-edit-saved')||'[]'))}catch{}
const notes=['Bright · bittersweet · balanced','Smoky · floral · bright','Crisp · tropical · dry','Earthy · smoky · citrusy','Fresh · tart · timeless','Warm · fragrant · crisp','Botanical · zesty · silky','Melon · citrus · playful','Herbal · smooth · comforting','Rich · bitter · warming','Botanical · bitter · aromatic','Tropical · rich · bittersweet','Aromatic · antique · elegant','Bold · herbal · classic','Cacao · spice · bittersweet','Smoky · dark · decadent','Creamy · indulgent · spiced','Botanical · bright · chocolate','Herbal · velvety · warming','Minty · herbal · effervescent'];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function spirits(r){let s=r.ingredients.join(' ');return ['Whisky','Gin','Rum','Mezcal','Brandy','Amaro'].filter(v=>new RegExp(v,'i').test(s))}
function mood(r){if(r.category.startsWith('Shaken'))return 'Bright';if(r.category.startsWith('Chocolate'))return 'Sweet';if(r.category.startsWith('Herbal'))return 'Herbal';return 'Bitter'}
function persist(){try{localStorage.setItem('evening-edit-saved',JSON.stringify([...saved]))}catch{}$('#saved-count').textContent=saved.size}
function save(i){if(saved.has(i)){saved.delete(i);toast('Removed from An Evening Dip')}else{saved.add(i);toast('Saved to An Evening Dip')}persist();render();if(state.active===i)updateSaveButton()}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function render(){const list=state.recipes.map((r,i)=>({...r,i})).filter(r=>(state.mood==='All'||mood(r)===state.mood)&&(state.spirit==='All'||(state.spirit==='Other'?spirits(r).length===0:spirits(r).includes(state.spirit)))&&(!state.savedOnly||saved.has(r.i))&&[r.name,r.description,...r.ingredients].join(' ').toLowerCase().includes(state.query.toLowerCase()));$('#grid').innerHTML=list.map(r=>`<article class="card"><button class="save ${saved.has(r.i)?'saved':''}" data-save="${r.i}" aria-label="${saved.has(r.i)?'Unsave':'Save'} ${escapeHTML(r.name)}" aria-pressed="${saved.has(r.i)}">${saved.has(r.i)?'♥':'♡'}</button><button class="card-open" data-open="${r.i}" aria-label="View ${escapeHTML(r.name)} recipe"><span class="card-art"><span class="card-number">${String(r.i+1).padStart(2,'0')} / 20</span><img src="${r.image}" alt="Illustration of ${escapeHTML(r.name)}" loading="lazy"></span><span class="card-meta">${spirits(r).join(' / ').toUpperCase()||'HERBAL LIQUEUR'} · ${/shake/i.test(r.preparation)?'SHAKEN':/highball/i.test(r.glassware)?'BUILT':'STIRRED'}</span><h3>${escapeHTML(r.name.replace(' (Mezcal Margarita)','').replace(' / Matacuy Spritz','').replace('Classic Negroni & Mezcal Negroni','Negroni, two ways'))}</h3><span class="card-foot"><span class="card-note">${notes[r.i]}</span><b aria-hidden="true">↗</b></span></button></article>`).join('');$('#empty').hidden=list.length>0;$('#result-count').textContent=`${list.length} cocktail${list.length===1?'':'s'}`;$('#saved-filter').setAttribute('aria-pressed',state.savedOnly);document.querySelectorAll('[data-mood]').forEach(b=>b.classList.toggle('active',b.dataset.mood===state.mood))}
function numeric(s){return s.trim().split(/\s+/).reduce((sum,v)=>sum+(v.includes('/')?Number(v.split('/')[0])/Number(v.split('/')[1]):Number(v)),0)}
function amount(n){const whole=Math.floor(n),frac=Math.round((n-whole)*12);const f={3:'¼',4:'⅓',6:'½',8:'⅔',9:'¾'}[frac];if(!frac)return String(whole);if(f)return (whole?whole+' ':'')+f;return String(Number(n.toFixed(2)))}
function scale(text){return text.replace(/(\d+(?:\s+\d+\/\d+|\/\d+)?)(\s+)(oz|dashes|dash|barspoon|egg white)(?=\b)/g,(match,n,space,unit)=>{const v=numeric(n)*state.servings;if(unit==='oz'&&state.unit==='ml')return `${Number((v*29.5735).toFixed(1))} ml`;return `${amount(v)} ${unit==='dash'&&v>1?'dashes':unit==='barspoon'&&v>1?'barspoons':unit==='egg white'&&v>1?'egg whites':unit}`})}
function ingredients(){const r=state.recipes[state.active];$('#ingredient-list').innerHTML=r.ingredients.map((text,i)=>`<label class="ingredient"><input type="checkbox" aria-label="${escapeHTML(text)}"><span>${escapeHTML(scale(text))}</span></label>`).join('');$('#serving-count').textContent=state.servings+' '+(state.servings===1?'serving':'servings');$('#decrease').disabled=state.servings<=1;$('#increase').disabled=state.servings>=12;document.querySelectorAll('[data-unit]').forEach(b=>{b.classList.toggle('active',b.dataset.unit===state.unit);b.setAttribute('aria-pressed',b.dataset.unit===state.unit)})}
function updateSaveButton(){const b=$('#detail-save');if(b){b.textContent=saved.has(state.active)?'♥ Saved to your collection':'♡ Save to your collection';b.setAttribute('aria-pressed',saved.has(state.active))}}
function openRecipe(i){if(!state.recipes[i])return;state.active=i;state.servings=1;const r=state.recipes[i];$('#recipe-content').innerHTML=`<div class="recipe-layout"><div class="recipe-visual"><p class="eyebrow">AN EVENING DIP / NO. ${String(i+1).padStart(2,'0')}</p><img src="${r.image}" alt="Illustration of ${escapeHTML(r.name)}"></div><div class="recipe-info"><p class="eyebrow">${escapeHTML(r.category)}</p><h2 id="recipe-title">${escapeHTML(r.name)}</h2><p class="story">${escapeHTML(r.description)}</p><div class="recipe-details"><span><b>THE GLASS</b>${escapeHTML(r.glassware)}</span><span><b>THE FINISH</b>${escapeHTML(r.garnish)}</span></div><div class="ingredients-heading"><h3>In the glass</h3><div class="servings"><button id="decrease" aria-label="Fewer servings">−</button><span id="serving-count">1 serving</span><button id="increase" aria-label="More servings">+</button></div></div><div class="unit-toggle" role="group" aria-label="Measurement unit"><button data-unit="oz">oz</button><button data-unit="ml">ml</button></div><div id="ingredient-list"></div><div style="margin-top:28px"><h3>The ritual</h3><p class="prep">${escapeHTML(r.preparation)}</p></div><div class="recipe-actions"><button id="detail-save" aria-pressed="false"></button><button id="next-recipe">Another evening’s pour ↗</button></div></div></div>`;ingredients();updateSaveButton();const dialog=$('#recipe-dialog');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');history.replaceState(null,'',`#recipe-${i+1}`);$('#decrease').onclick=()=>{if(state.servings>1){state.servings--;ingredients()}};$('#increase').onclick=()=>{if(state.servings<12){state.servings++;ingredients()}};document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{state.unit=b.dataset.unit;ingredients()});$('#detail-save').onclick=()=>save(i);$('#next-recipe').onclick=()=>openRecipe((i+1)%state.recipes.length)}
function closeRecipe(){const dialog=$('#recipe-dialog');dialog.close();document.body.classList.remove('modal-open');state.active=null;history.replaceState(null,'','#collection')}
$('#grid').onclick=e=>{const saveButton=e.target.closest('[data-save]');const openButton=e.target.closest('[data-open]');if(saveButton)save(Number(saveButton.dataset.save));else if(openButton)openRecipe(Number(openButton.dataset.open))};document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{state.mood=b.dataset.mood;render()});$('#spirit').onchange=e=>{state.spirit=e.target.value;render()};$('#search').oninput=e=>{state.query=e.target.value;render()};$('#saved-filter').onclick=()=>{state.savedOnly=!state.savedOnly;render()};$('#saved-nav').onclick=()=>{state.savedOnly=true;state.mood='All';state.spirit='All';state.query='';$('#search').value='';$('#spirit').value='All';render();$('#collection').scrollIntoView({behavior:'smooth'})};$('#reset').onclick=()=>{state.savedOnly=false;state.mood='All';state.spirit='All';state.query='';$('#search').value='';$('#spirit').value='All';render()};$('#surprise').onclick=()=>openRecipe(Math.floor(Math.random()*state.recipes.length));$('.close-dialog').onclick=closeRecipe;$('#recipe-dialog').addEventListener('cancel',e=>{e.preventDefault();closeRecipe()});$('#recipe-dialog').addEventListener('click',e=>{if(e.target===$('#recipe-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeRecipe()}});
fetch('recipes.json').then(r=>{if(!r.ok)throw Error('Could not load recipes');return r.json()}).then(r=>{state.recipes=r;persist();render();renderFeatured();const match=location.hash.match(/^#recipe-(\d+)$/);if(match)openRecipe(Number(match[1])-1)}).catch(()=>{$('#grid').innerHTML='<p>The collection could not load. Please refresh to try again.</p>'});

function renderFeatured(){
 const picks=state.recipes.map((r,i)=>({...r,i}));
 for(let i=picks.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[picks[i],picks[j]]=[picks[j],picks[i]]}
 const track=$('#featured-track');
 track.innerHTML=picks.slice(0,3).map((r,n)=>`<button class="hero-art featured-slide" data-open="${r.i}" aria-label="Recommendation ${n+1} of 3: view ${escapeHTML(r.name)} recipe"><span class="art-label">TONIGHT’S PICK · ${n+1} OF 3</span><span class="hero-number" aria-hidden="true">${String(n+1).padStart(2,'0')}</span><img src="${r.image}" alt="Watercolor illustration of ${escapeHTML(r.name)}" ${n===0?'fetchpriority="high"':'loading="lazy"'}><span class="art-caption"><span><i>${notes[r.i]}</i><strong>${escapeHTML(r.name.replace(' (Mezcal Margarita)','').replace(' / Matacuy Spritz',''))}</strong></span><span class="round-arrow" aria-hidden="true">↗</span></span></button>`).join('')+`<a class="hero-art featured-slide featured-more" href="#collection"><span class="art-label">YOUR NEXT EVENING AWAITS</span><span class="more-star" aria-hidden="true">✳</span><span class="more-copy"><strong>See more.</strong><span>Twenty cocktails.<br>Find your next favorite.</span></span><span class="art-caption"><span>Explore the collection</span><span class="round-arrow" aria-hidden="true">↗</span></span></a>`;
 track.onclick=e=>{const b=e.target.closest('[data-open]');if(b)openRecipe(Number(b.dataset.open))};
 const slides=[...track.children];
 const current=()=>slides.reduce((best,s,i)=>Math.abs(s.offsetLeft-track.offsetLeft-track.scrollLeft)<Math.abs(slides[best].offsetLeft-track.offsetLeft-track.scrollLeft)?i:best,0);
 const go=i=>track.scrollTo({left:slides[Math.max(0,Math.min(i,slides.length-1))].offsetLeft-track.offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 $('#featured-prev').onclick=()=>go(current()-1);$('#featured-next').onclick=()=>go(current()+1);
 track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(current()+(e.key==='ArrowRight'?1:-1))}});
 track.addEventListener('scroll',()=>{const i=current();$('#featured-position').textContent=`TONIGHT’S PICKS · ${i+1} / ${slides.length}`;$('#featured-prev').disabled=i===0;$('#featured-next').disabled=i===slides.length-1},{passive:true});
}
